window.SEG=[{"i": 0, "a": 0.25, "b": 1.565, "text": "أبوي كان يطالعني…"}, {"i": 1, "a": 1.857, "b": 2.732, "text": "ويطالع الباب…"}, {"i": 2, "a": 3.051, "b": 4.949, "text": "وما يدري مين فينا نواف الحقيقي!"}, {"i": 3, "a": 5.316, "b": 7.005, "text": "والصوت من ورا الباب رجع يقول:"}, {"i": 4, "a": 7.355, "b": 9.527, "text": "«يبه… لا تصدقه! أنا ولدك!»"}, {"i": 5, "a": 9.883, "b": 12.395, "text": "هنا أبوي رفع يده وقال بصوت مرتجف:"}, {"i": 6, "a": 12.73, "b": 14.115, "text": "«وقفوا… لا أحد يتكلم!»"}, {"i": 7, "a": 14.519, "b": 15.335, "text": "لكن الصدمة…"}, {"i": 8, "a": 15.671, "b": 18.687, "text": "إني أنا واللي ورا الباب قلنا بنفس اللحظة:"}, {"i": 9, "a": 19.036, "b": 19.392, "text": "«يبه…"}, {"i": 10, "a": 19.783, "b": 20.531, "text": "أنا ما أتكلم!»"}, {"i": 11, "a": 20.972, "b": 22.183, "text": "تجمد أبوي…"}, {"i": 12, "a": 22.509, "b": 23.482, "text": "وتراجع أكثر…"}, {"i": 13, "a": 23.784, "b": 25.462, "text": "وبدأ يطالعني كأني غريب."}, {"i": 14, "a": 25.839, "b": 26.276, "text": "وفجأة…"}, {"i": 15, "a": 26.573, "b": 28.344, "text": "جات ثلاث دقات أقوى…"}, {"i": 16, "a": 28.651, "b": 28.973, "text": "طق…"}, {"i": 17, "a": 29.21, "b": 29.535, "text": "طق…"}, {"i": 18, "a": 29.772, "b": 30.118, "text": "طق…"}, {"i": 19, "a": 30.473, "b": 31.022, "text": "وبعدها…"}, {"i": 20, "a": 31.306, "b": 32.656, "text": "انفتح باب الشقة…"}, {"i": 21, "a": 32.953, "b": 33.448, "text": "لحاله!"}, {"i": 22, "a": 33.778, "b": 35.288, "text": "أبوي ركض بسرعة وقفله،"}, {"i": 23, "a": 35.537, "b": 37.496, "text": "وحط يده على المقبض…"}, {"i": 24, "a": 37.791, "b": 39.476, "text": "وبعدين لف علي وقال:"}, {"i": 25, "a": 39.771, "b": 40.947, "text": "«تعال معي! الحين!»"}, {"i": 26, "a": 41.333, "b": 42.775, "text": "سحبني وطلعني من الشقة…"}, {"i": 27, "a": 43.037, "b": 43.776, "text": "مو للدرج…"}, {"i": 28, "a": 43.999, "b": 44.798, "text": "ولا للمصعد…"}, {"i": 29, "a": 45.036, "b": 46.215, "text": "لكن لآخر الممر…"}, {"i": 30, "a": 46.474, "b": 48.301, "text": "عند غرفة صغيرة ما قد انتبهت لها."}, {"i": 31, "a": 48.644, "b": 49.626, "text": "غرفة الحارس."}, {"i": 32, "a": 49.949, "b": 51.297, "text": "دق أبوي الباب بقوة…"}, {"i": 33, "a": 51.619, "b": 52.809, "text": "فتح لنا أبو صالح."}, {"i": 34, "a": 53.132, "b": 53.99, "text": "أول ما شافني…"}, {"i": 35, "a": 54.25, "b": 54.992, "text": "تغير وجهه…"}, {"i": 36, "a": 55.305, "b": 56.568, "text": "وطالع في أبوي وقال:"}, {"i": 37, "a": 56.88, "b": 57.63, "text": "«لا تقول لي…"}, {"i": 38, "a": 57.896, "b": 58.863, "text": "رجعوا مرة ثانية؟»"}, {"i": 39, "a": 59.245, "b": 59.964, "text": "دخلنا…"}, {"i": 40, "a": 60.315, "b": 62.96, "text": "كانت صغيرة ومليانة شاشات مراقبة قديمة،"}, {"i": 41, "a": 63.202, "b": 64.816, "text": "وأشرطة فيديو فوق الرفوف."}, {"i": 42, "a": 65.185, "b": 65.617, "text": "قلت:"}, {"i": 43, "a": 65.928, "b": 66.56, "text": "«أبو صالح…"}, {"i": 44, "a": 66.827, "b": 67.616, "text": "وش قاعد يصير؟»"}, {"i": 45, "a": 67.955, "b": 68.874, "text": "طالع فيني شوي…"}, {"i": 46, "a": 69.141, "b": 69.614, "text": "وقال:"}, {"i": 47, "a": 69.918, "b": 71.183, "text": "«قبل سبع سنوات…"}, {"i": 48, "a": 71.433, "b": 72.949, "text": "ما كان فيه نواف واحد."}, {"i": 49, "a": 73.286, "b": 74.097, "text": "كان فيه اثنين.»"}, {"i": 50, "a": 74.477, "b": 75.521, "text": "قلت له: «أنا مصدوم…"}, {"i": 51, "a": 75.834, "b": 77.015, "text": "يعني أنت بعد تعرف؟»"}, {"i": 52, "a": 77.323, "b": 77.757, "text": "قال:"}, {"i": 53, "a": 78.039, "b": 79.415, "text": "«أنا أول واحد شافكم.»"}, {"i": 54, "a": 79.779, "b": 80.906, "text": "وسحب شريط…"}, {"i": 55, "a": 81.135, "b": 82.421, "text": "وحطه في جهاز التشغيل."}, {"i": 56, "a": 82.76, "b": 83.141, "text": "قال:"}, {"i": 57, "a": 83.447, "b": 84.269, "text": "«شوفوا بنفسكم.»"}, {"i": 58, "a": 84.647, "b": 85.575, "text": "اشتغل التسجيل…"}, {"i": 59, "a": 85.925, "b": 87.238, "text": "وكان من يوم الحريق."}, {"i": 60, "a": 87.61, "b": 88.874, "text": "الممر مليان دخان…"}, {"i": 61, "a": 89.189, "b": 90.534, "text": "ورجال الإطفاء…"}, {"i": 62, "a": 90.845, "b": 92.227, "text": "وأبو صالح يصرخ:"}, {"i": 63, "a": 92.477, "b": 93.31, "text": "«لا تطلعونه!»"}, {"i": 64, "a": 93.602, "b": 96.479, "text": "واحد من الرجال قال: «وش فيك؟ الولد معنا!»"}, {"i": 65, "a": 96.737, "b": 98.267, "text": "لكن أبو صالح صرخ:"}, {"i": 66, "a": 98.569, "b": 100.364, "text": "«الولد الحقيقي للحين تحت!»"}, {"i": 67, "a": 100.673, "b": 102.221, "text": "حسيت جسمي كله برد."}, {"i": 68, "a": 102.512, "b": 103.198, "text": "طالعت أبوي…"}, {"i": 69, "a": 103.464, "b": 104.424, "text": "كان منزل راسه."}, {"i": 70, "a": 104.732, "b": 105.183, "text": "قلت:"}, {"i": 71, "a": 105.49, "b": 105.924, "text": "«يعني…"}, {"i": 72, "a": 106.252, "b": 107.679, "text": "أنت كنت تعرف من البداية؟»"}, {"i": 73, "a": 108.011, "b": 108.695, "text": "قال بهدوء:"}, {"i": 74, "a": 109.054, "b": 111.097, "text": "«كنت أعرف إن واحد فيكم مو أنت…"}, {"i": 75, "a": 111.459, "b": 112.688, "text": "لكن ما كنت أعرف مين.»"}, {"i": 76, "a": 113.108, "b": 114.269, "text": "ورجعت أطالع الشاشة…"}, {"i": 77, "a": 114.572, "b": 117.597, "text": "وفي التسجيل بان ولد يشبهني يطلع من المصعد."}, {"i": 78, "a": 117.867, "b": 118.782, "text": "وبعد ثواني…"}, {"i": 79, "a": 119.034, "b": 119.891, "text": "طلع وراه…"}, {"i": 80, "a": 120.185, "b": 120.87, "text": "نفس الوجه…"}, {"i": 81, "a": 121.149, "b": 121.953, "text": "نفس الملابس…"}, {"i": 82, "a": 122.203, "b": 123.109, "text": "نفس كل شي…"}, {"i": 83, "a": 123.432, "b": 124.629, "text": "واحد منهم كان يبكي…"}, {"i": 84, "a": 124.967, "b": 125.506, "text": "والثاني…"}, {"i": 85, "a": 125.738, "b": 127.307, "text": "كان ساكت ويطالع الكاميرا."}, {"i": 86, "a": 127.632, "b": 129.058, "text": "وقبل ما ينتهي التسجيل…"}, {"i": 87, "a": 129.298, "b": 131.057, "text": "أبو صالح وقف المقطع وقال:"}, {"i": 88, "a": 131.328, "b": 131.81, "text": "«وهنا…"}, {"i": 89, "a": 132.081, "b": 132.984, "text": "بدأت المشكلة.»"}, {"i": 90, "a": 133.355, "b": 133.789, "text": "قلت:"}, {"i": 91, "a": 134.093, "b": 134.466, "text": "«طيب…"}, {"i": 92, "a": 134.687, "b": 135.543, "text": "ليش ما قلتوا لي؟»"}, {"i": 93, "a": 135.848, "b": 136.708, "text": "قال أبو صالح:"}, {"i": 94, "a": 136.973, "b": 138.905, "text": "«لأن كل ما تقترب من الحقيقة…"}, {"i": 95, "a": 139.135, "b": 140.2, "text": "هو يقرب أكثر.»"}, {"i": 96, "a": 140.586, "b": 142.017, "text": "استوعبت كلامه وقلت:"}, {"i": 97, "a": 142.294, "b": 142.603, "text": "«هو؟"}, {"i": 98, "a": 142.934, "b": 143.372, "text": "مين هو؟»"}, {"i": 99, "a": 143.702, "b": 146.517, "text": "أبو صالح ما رد، بس أشار لشاشات المراقبة…"}, {"i": 100, "a": 146.809, "b": 147.225, "text": "قال:"}, {"i": 101, "a": 147.484, "b": 148.684, "text": "«الأهم من هذا كله…"}, {"i": 102, "a": 148.967, "b": 150.173, "text": "شوف البث المباشر.»"}, {"i": 103, "a": 150.513, "b": 151.35, "text": "طالعنا الشاشة…"}, {"i": 104, "a": 151.615, "b": 153.63, "text": "وكانت الكاميرا تعرض باب شقتنا…"}, {"i": 105, "a": 153.932, "b": 154.475, "text": "والباب…"}, {"i": 106, "a": 154.715, "b": 155.537, "text": "كان مفتوح."}, {"i": 107, "a": 155.857, "b": 157.301, "text": "طلع شخص من داخلها…"}, {"i": 108, "a": 157.549, "b": 158.846, "text": "قرب من الكاميرا شوي…"}, {"i": 109, "a": 159.136, "b": 159.55, "text": "وهنا…"}, {"i": 110, "a": 159.781, "b": 161.001, "text": "حسيت قلبي وقف."}, {"i": 111, "a": 161.372, "b": 161.956, "text": "كان أنا."}, {"i": 112, "a": 162.288, "b": 164.182, "text": "طلع من الشقة ومشى في الممر…"}, {"i": 113, "a": 164.476, "b": 166.671, "text": "ثم وقف قدام غرفة الحارس مباشرة…"}, {"i": 114, "a": 166.973, "b": 168.21, "text": "ورفع راسه للكاميرا…"}, {"i": 115, "a": 168.483, "b": 168.918, "text": "وابتسم."}, {"i": 116, "a": 169.299, "b": 169.866, "text": "وبعدين…"}, {"i": 117, "a": 170.102, "b": 171.055, "text": "قال بصوتي أنا:"}, {"i": 118, "a": 171.372, "b": 172.447, "text": "«إذا خلصتوا فرجة…"}, {"i": 119, "a": 172.719, "b": 173.417, "text": "افتحوا الباب.»"}, {"i": 120, "a": 173.802, "b": 175.823, "text": "كلنا التفتنا لباب غرفة الحارس…"}, {"i": 121, "a": 176.067, "b": 177.807, "text": "لأننا سمعنا في نفس اللحظة…"}, {"i": 122, "a": 178.085, "b": 179.581, "text": "ثلاث دقات على الباب."}, {"i": 123, "a": 179.852, "b": 180.174, "text": "طق…"}, {"i": 124, "a": 180.476, "b": 180.807, "text": "طق…"}, {"i": 125, "a": 181.065, "b": 181.431, "text": "طق…"}, {"i": 126, "a": 181.858, "b": 182.944, "text": "والحين أبي أسألكم…"}, {"i": 127, "a": 183.285, "b": 185.059, "text": "لو كنتوا مكان أبوي وأبو صالح…"}, {"i": 128, "a": 185.331, "b": 186.875, "text": "بتفتحون الباب وتواجهونه؟"}, {"i": 129, "a": 187.199, "b": 189.481, "text": "ولا بتقفلون الباب وتنتظرون؟"}];
